classes.code:
public class Weight {
    private int kilo;
    private int gram;

    public Weight() {
        kilo = 0;
        gram = 0;
    }

    public int getKilo() { return kilo; }
    public void setKilo(int kilo) { this.kilo = kilo; }
    public int getGram() { return gram; }
    public void setGram(int gram) { this.gram = gram; }

    public String toString() {
        return kilo + " ק\"ג " + gram + " גרם";
    }
}

public class AllWeights {
    private Weight[] arr;

    public AllWeights(Weight[] arr) {
        this.arr = arr;
    }

    public Weight[] getArr() { return arr; }
}

tasks.solution:
public Weight(int kilo, int gram) {
    this.kilo = kilo;
    this.gram = gram;
}

public Weight(int totalGram) {
    kilo = totalGram / 1000;
    gram = totalGram % 1000;
}

public void add(Weight other) {
    gram = gram + other.getGram();
    kilo = kilo + other.getKilo() + gram / 1000;   // מעבר של 1000 גרם לקילו
    gram = gram % 1000;
}

public boolean less(Weight other) {
    if (kilo < other.getKilo()) {
        return true;
    }
    return kilo == other.getKilo() && gram < other.getGram();
}

public Weight sum() {
    Weight total = new Weight();
    for (int i = 0; i < arr.length; i++) {
        total.add(arr[i]);   // total משתנה, איברי המערך לא
    }
    return total;
}

